'use strict';

/**
 * Single source of truth for the order lifecycle finite state machine.
 * Maps each status to the array of statuses it may legally transition to.
 * `delivered` and `cancelled` are terminal (empty arrays).
 */
const TRANSITIONS = Object.freeze({
  pending: Object.freeze(['paid', 'cancelled']),
  paid: Object.freeze(['shipped', 'cancelled']),
  shipped: Object.freeze(['delivered']),
  delivered: Object.freeze([]),
  cancelled: Object.freeze([]),
});

const ALL_STATUSES = Object.freeze(Object.keys(TRANSITIONS));

function isValidStatus(status) {
  return Object.prototype.hasOwnProperty.call(TRANSITIONS, status);
}

function isLegalTransition(from, to) {
  const allowed = TRANSITIONS[from];
  return Array.isArray(allowed) && allowed.includes(to);
}

function getTransitionTable() {
  const table = {};
  for (const status of ALL_STATUSES) {
    table[status] = [...TRANSITIONS[status]].sort();
  }
  return table;
}

module.exports = {
  TRANSITIONS,
  ALL_STATUSES,
  isValidStatus,
  isLegalTransition,
  getTransitionTable,
};

'use strict';

const { Sequelize, DataTypes, Transaction } = require('sequelize');

/**
 * Create a Sequelize instance backed by a file-based SQLite database.
 */
function createSequelize(storagePath) {
  return new Sequelize({
    dialect: 'sqlite',
    storage: storagePath,
    logging: false,
    // Only one sqlite connection is ever needed; this also keeps behaviour
    // predictable with respect to file-level locking across separate
    // invocations of the CLI operating on the same database file.
    pool: { max: 1, min: 0, idle: 10000 },
  });
}

function defineModels(sequelize) {
  const Order = sequelize.define(
    'Order',
    {
      id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true,
      },
      status: {
        type: DataTypes.STRING,
        allowNull: false,
        defaultValue: 'pending',
      },
    },
    {
      tableName: 'Orders',
      timestamps: false,
    }
  );

  const OrderStatusHistory = sequelize.define(
    'OrderStatusHistory',
    {
      id: {
        type: DataTypes.INTEGER,
        primaryKey: true,
        autoIncrement: true,
      },
      orderId: {
        type: DataTypes.INTEGER,
        allowNull: false,
      },
      fromStatus: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      toStatus: {
        type: DataTypes.STRING,
        allowNull: false,
      },
      at: {
        type: DataTypes.DATE,
        allowNull: false,
      },
    },
    {
      tableName: 'OrderStatusHistories',
      timestamps: false,
    }
  );

  Order.hasMany(OrderStatusHistory, { foreignKey: 'orderId', as: 'history' });
  OrderStatusHistory.belongsTo(Order, { foreignKey: 'orderId' });

  return { Order, OrderStatusHistory };
}

/**
 * Ensure the schema required by this application exists on the given
 * database file. Safe to call every time the CLI runs; uses
 * `CREATE TABLE IF NOT EXISTS` so it is idempotent and does not clobber
 * existing data.
 */
async function ensureSchema(sequelize) {
  await sequelize.query(`
    CREATE TABLE IF NOT EXISTS "Orders" (
      "id" INTEGER PRIMARY KEY AUTOINCREMENT,
      "status" TEXT NOT NULL DEFAULT 'pending'
    );
  `);

  await sequelize.query(`
    CREATE TABLE IF NOT EXISTS "OrderStatusHistories" (
      "id" INTEGER PRIMARY KEY AUTOINCREMENT,
      "orderId" INTEGER NOT NULL,
      "fromStatus" TEXT NOT NULL,
      "toStatus" TEXT NOT NULL,
      "at" DATETIME NOT NULL,
      FOREIGN KEY ("orderId") REFERENCES "Orders" ("id")
    );
  `);

  await sequelize.query(`
    CREATE INDEX IF NOT EXISTS "idx_order_status_histories_order_id"
    ON "OrderStatusHistories" ("orderId");
  `);
}

/**
 * Give sqlite's own busy-handler a chance to wait for locks held by other
 * processes/connections instead of failing immediately with SQLITE_BUSY.
 * This is a defense-in-depth measure; the primary safety mechanism is the
 * IMMEDIATE transaction used for every mutating operation, combined with
 * application-level retries.
 */
async function configureConnection(sequelize) {
  await sequelize.query('PRAGMA busy_timeout = 30000;');
}

module.exports = {
  createSequelize,
  defineModels,
  ensureSchema,
  configureConnection,
  Transaction,
};

'use strict';

const { Transaction } = require('./db');
const { isLegalTransition } = require('./transitions');

function isBusyError(err) {
  const codes = new Set(['SQLITE_BUSY', 'SQLITE_LOCKED']);
  if (err && err.original && codes.has(err.original.code)) return true;
  if (err && err.parent && codes.has(err.parent.code)) return true;
  if (err && codes.has(err.code)) return true;
  return false;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Retry a function on transient sqlite "busy"/"locked" errors that can
 * surface when multiple separate processes contend for the same database
 * file's write lock. Uses a small randomized backoff.
 */
async function withBusyRetry(fn, { retries = 20, baseDelayMs = 15 } = {}) {
  let attempt = 0;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt += 1;
      if (attempt >= retries || !isBusyError(err)) {
        throw err;
      }
      await sleep(baseDelayMs + Math.random() * baseDelayMs * attempt);
    }
  }
}

/**
 * Create a new order in the initial `pending` state.
 */
async function createOrder(sequelize, { Order }) {
  const order = await Order.create({ status: 'pending' });
  return { id: order.id, status: order.status };
}

/**
 * Attempt to transition an order to a new status.
 *
 * Runs inside a sqlite IMMEDIATE transaction, which acquires sqlite's
 * reserved write lock at the start of the transaction (rather than lazily
 * on the first write). Combined with the fact that sqlite only ever allows
 * a single writer, this fully serializes concurrent transition attempts
 * against the same order (or any order in the same database file): only
 * one such transaction can be in its critical section (read status ->
 * decide legality -> write status + history) at a time, so the
 * read-then-write is effectively atomic and race-free, even across
 * separate OS processes.
 *
 * Returns a plain result object describing the outcome; never throws for
 * expected business-logic outcomes (not found / illegal transition).
 */
async function transitionOrder(sequelize, { Order, OrderStatusHistory }, id, to) {
  return withBusyRetry(() =>
    sequelize.transaction({ type: Transaction.TYPES.IMMEDIATE }, async (t) => {
      const order = await Order.findByPk(id, { transaction: t });

      if (!order) {
        return { ok: false, error: 'NOT_FOUND', id };
      }

      const from = order.status;

      if (!isLegalTransition(from, to)) {
        return { ok: false, error: 'ILLEGAL_TRANSITION', id, from, to };
      }

      order.status = to;
      await order.save({ transaction: t });

      await OrderStatusHistory.create(
        {
          orderId: id,
          fromStatus: from,
          toStatus: to,
          at: new Date(),
        },
        { transaction: t }
      );

      return { ok: true, id, from, to };
    })
  );
}

/**
 * Fetch an order along with its full, chronologically ordered history.
 * Returns null if the order does not exist.
 */
async function getOrderWithHistory(sequelize, { Order, OrderStatusHistory }, id) {
  const order = await Order.findByPk(id);
  if (!order) {
    return null;
  }

  const rows = await OrderStatusHistory.findAll({
    where: { orderId: id },
    order: [
      ['at', 'ASC'],
      ['id', 'ASC'],
    ],
  });

  const history = rows.map((row) => ({
    fromStatus: row.fromStatus,
    toStatus: row.toStatus,
    at: new Date(row.at).toISOString(),
  }));

  return { id: order.id, status: order.status, history };
}

module.exports = {
  createOrder,
  transitionOrder,
  getOrderWithHistory,
  withBusyRetry,
};

#!/usr/bin/env node
'use strict';

const {
  createSequelize,
  defineModels,
  ensureSchema,
  configureConnection,
} = require('./db');
const { getTransitionTable, isValidStatus } = require('./transitions');
const {
  createOrder,
  transitionOrder,
  getOrderWithHistory,
} = require('./orderService');

function parseArgs(argv) {
  const args = {};
  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i];
    if (token.startsWith('--')) {
      const key = token.slice(2);
      const next = argv[i + 1];
      if (next === undefined || next.startsWith('--')) {
        args[key] = true;
      } else {
        args[key] = next;
        i += 1;
      }
    }
  }
  return args;
}

function printJson(value) {
  process.stdout.write(`${JSON.stringify(value)}\n`);
}

function fail(message) {
  process.stderr.write(`${message}\n`);
  process.exitCode = 1;
}

async function main() {
  const [subcommand, ...rest] = process.argv.slice(2);
  const args = parseArgs(rest);

  if (!subcommand) {
    fail('Usage: node cli.js <subcommand> --db <path> [options]');
    return;
  }

  if (!args.db || typeof args.db !== 'string') {
    fail('Missing required --db <path> argument.');
    return;
  }

  const sequelize = createSequelize(args.db);
  let exitCode = 0;

  try {
    await configureConnection(sequelize);
    await ensureSchema(sequelize);
    const models = defineModels(sequelize);

    switch (subcommand) {
      case 'init': {
        printJson({ ok: true });
        exitCode = 0;
        break;
      }

      case 'create': {
        const result = await createOrder(sequelize, models);
        printJson(result);
        exitCode = 0;
        break;
      }

      case 'transition': {
        if (args.id === undefined || args.to === undefined) {
          fail('Usage: node cli.js transition --db <path> --id <number> --to <status>');
          exitCode = 1;
          break;
        }
        const id = Number.parseInt(args.id, 10);
        const to = String(args.to);

        if (!Number.isInteger(id)) {
          fail(`Invalid --id value: ${args.id}`);
          exitCode = 1;
          break;
        }
        if (!isValidStatus(to)) {
          // Not a recognized status at all: still surface an illegal
          // transition result rather than a generic error, per spec this
          // counts as an illegal transition attempt.
          const order = await models.Order.findByPk(id);
          if (!order) {
            printJson({ ok: false, error: 'NOT_FOUND', id });
            exitCode = 4;
            break;
          }
          printJson({ ok: false, error: 'ILLEGAL_TRANSITION', id, from: order.status, to });
          exitCode = 3;
          break;
        }

        const result = await transitionOrder(sequelize, models, id, to);
        printJson(result);
        if (result.ok) {
          exitCode = 0;
        } else if (result.error === 'NOT_FOUND') {
          exitCode = 4;
        } else {
          exitCode = 3;
        }
        break;
      }

      case 'show': {
        if (args.id === undefined) {
          fail('Usage: node cli.js show --db <path> --id <number>');
          exitCode = 1;
          break;
        }
        const id = Number.parseInt(args.id, 10);
        if (!Number.isInteger(id)) {
          fail(`Invalid --id value: ${args.id}`);
          exitCode = 1;
          break;
        }

        const result = await getOrderWithHistory(sequelize, models, id);
        if (!result) {
          printJson({ ok: false, error: 'NOT_FOUND', id });
          exitCode = 4;
        } else {
          printJson(result);
          exitCode = 0;
        }
        break;
      }

      case 'transitions': {
        printJson(getTransitionTable());
        exitCode = 0;
        break;
      }

      default: {
        fail(`Unknown subcommand: ${subcommand}`);
        exitCode = 1;
      }
    }
  } catch (err) {
    process.stderr.write(`${err && err.stack ? err.stack : String(err)}\n`);
    exitCode = 1;
  } finally {
    await sequelize.close();
  }

  process.exitCode = exitCode;
}

main();

